links = {
    "Wiki": ["Gem"],
    "News": ["Wiki"],
    "Gem":  ["Wiki", "News"],
    "Spam": ["News"],
    "fan1": ["Spam"],
    "fan2": ["Spam"],
    "fan3": ["Spam"],
}
pages = list(links)
n = len(pages)

# the obvious way: count incoming links
naive = {p: 0 for p in pages}
for p in pages:
    for target in links[p]:
        naive[target] += 1

# the clever way: pass rank along links
d = 0.85
rank = {p: 1 / n for p in pages}
for step in range(30):
    new = {p: (1 - d) / n for p in pages}
    for p in pages:
        share = rank[p] / len(links[p])
        for target in links[p]:
            new[target] += d * share
    change = sum(abs(new[p] - rank[p]) for p in pages)
    rank = new
    if step % 5 == 0:
        print(f"round {step:2d}: change = {change:.5f}")

show([naive[p] for p in pages], "naive: incoming links")
show([round(rank[p], 3) for p in pages], "PageRank")
print("order:", pages)

