const start = {
  box:  { x: 0, color: "blue" },
  star: { x: 5, color: "gold" }
};
const edits = [
  { who: "Ana", time: 1, id: "box",  props: { x: 100 } },
  { who: "Ben", time: 2, id: "box",  props: { color: "red" } },
  { who: "Ana", time: 3, id: "star", props: { x: 50 } },
  { who: "Ben", time: 4, id: "star", props: { x: 80 } }
];
const inOrder = [...edits].sort((a, b) => a.time - b.time);

function wholeObject(doc, edit) {
  doc[edit.id] = { ...start[edit.id], ...edit.props };
}
function perProperty(doc, edit) {
  Object.assign(doc[edit.id], edit.props);
}

function merge(applyEdit) {
  const doc = JSON.parse(JSON.stringify(start));
  for (const edit of inOrder) applyEdit(doc, edit);
  return doc;
}

function lostEdits(doc) {
  return edits.filter(e =>
    Object.entries(e.props).some(([k, v]) => doc[e.id][k] !== v));
}

for (const [name, fn] of [["Whole object", wholeObject], ["Per property", perProperty]]) {
  const doc = merge(fn);
  const lost = lostEdits(doc).map(e => e.who + " @" + e.time);
  print(name + " lost: " + (lost.join(", ") || "nothing"));
  show(doc, name);
}

