old = ["roses are red", "violets are blue", "sugar is sweet", "and so are you"]
new = ["a poem:", "roses are red", "violets are purple", "and so are you"]

def naive(a, b):
    out = []
    for i in range(max(len(a), len(b))):
        x = a[i] if i < len(a) else None
        y = b[i] if i < len(b) else None
        if x == y:
            out.append("  " + x)
        else:
            if x: out.append("- " + x)
            if y: out.append("+ " + y)
    return out

def lcs_table(a, b):
    t = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) - 1, -1, -1):
        for j in range(len(b) - 1, -1, -1):
            if a[i] == b[j]:
                t[i][j] = 1 + t[i + 1][j + 1]
            else:
                t[i][j] = max(t[i + 1][j], t[i][j + 1])
    return t

def smart(a, b):
    t = lcs_table(a, b)
    i, j, out = 0, 0, []
    while i < len(a) or j < len(b):
        if i < len(a) and j < len(b) and a[i] == b[j]:
            out.append("  " + a[i])
            i += 1
            j += 1
        elif i < len(a) and (j == len(b) or t[i + 1][j] >= t[i][j + 1]):
            out.append("- " + a[i])
            i += 1
        else:
            out.append("+ " + b[j])
            j += 1
    return out

show(lcs_table(old, new), "LCS table: old lines down, new across")
results = {"naive": naive(old, new), "smart": smart(old, new)}
for name, diff in results.items():
    print(name, "diff:\n" + "\n".join(diff))
show({n: sum(l[0] != " " for l in d) for n, d in results.items()}, "changed lines")

