import copy, hashlib

def sha(text):
    return hashlib.sha1(text.encode()).hexdigest()[:7]

def build(node):
    if isinstance(node, str):
        return {"hash": sha(node), "kids": {}}
    kids = {n: build(c) for n, c in sorted(node.items())}
    joined = "".join(n + k["hash"] for n, k in kids.items())
    return {"hash": sha(joined), "kids": kids}

def walk(a, b, path, count):
    count[0] += 1
    if a["hash"] == b["hash"]:
        return []
    if not a["kids"]:
        return [path]
    found = []
    for name in a["kids"]:
        found += walk(a["kids"][name], b["kids"][name], path + "/" + name, count)
    return found

def flat(node, path=""):
    if isinstance(node, str):
        return {path: node}
    return {k: v for n, c in node.items() for k, v in flat(c, path + "/" + n).items()}

project = {f"dir{d}": {f"f{i}.txt": f"data {d}-{i}" for i in range(20)} for d in range(6)}
edited = copy.deepcopy(project)
edited["dir3"]["f7.txt"] = "data 3-7 EDITED"

old, new = build(project), build(edited)
show({n: k["hash"] for n, k in old["kids"].items()}, "before: folder fingerprints")
show({n: k["hash"] for n, k in new["kids"].items()}, "after: dir3 changed")

a, b = flat(project), flat(edited)
slow = [p for p in a if a[p] != b[p]]
count = [0]
fast = walk(old, new, "", count)
show({"obvious way": len(a), "clever way": count[0]}, "comparisons")
print(slow == fast, fast)

