import random
random.seed(7)

songs = {n: [(t, random.randint(1, 40)) for t in range(60)]
         for n in ["Aria", "Blues", "Cumbia"]}

def hashes(peaks):
    return [((f1, f2, t2 - t1), t1)
            for t1, f1 in peaks for t2, f2 in peaks if 0 < t2 - t1 <= 3]

index = {}
for name, peaks in songs.items():
    for h, t in hashes(peaks):
        index.setdefault(h, []).append((name, t))

clip = [(t - 20, f) for t, f in songs["Blues"] if 20 <= t < 30]
heard = [p for p in clip if random.random() > 0.3]
heard += [(random.randint(0, 9), random.randint(1, 40)) for _ in range(8)]

def naive(sample):
    for name, peaks in songs.items():
        for s in range(50):
            window = [(t - s, f) for t, f in peaks if s <= t < s + 10]
            if sorted(window) == sorted(sample):
                return name
    return "no match"

show({"clean clip": naive(clip), "noisy clip": naive(heard)}, "Obvious way")

votes = {}
for h, t in hashes(heard):
    for name, song_t in index.get(h, []):
        key = (name, song_t - t)
        votes[key] = votes.get(key, 0) + 1

best = {n: max([v for (s, _), v in votes.items() if s == n], default=0) for n in songs}
show(list(best.values()), "Votes at best offset: Aria, Blues, Cumbia")
print(best)

