import hashlib
from bisect import bisect

def h(text):
    return int(hashlib.md5(text.encode()).hexdigest()[:8], 16)

def modulo_owner(key, servers):
    return servers[h(key) % len(servers)]

def build_ring(servers, vnodes=50):
    points = [(h(f"{s}#{v}"), s) for s in servers for v in range(vnodes)]
    return sorted(points)

def ring_owner(key, ring):
    i = bisect(ring, (h(key), "")) % len(ring)
    return ring[i][1]

keys = [f"guild{i}" for i in range(1000)]
old = ["A", "B", "C", "D"]
new = old + ["E"]
ring_old, ring_new = build_ring(old), build_ring(new)

mod_moved = sum(modulo_owner(k, old) != modulo_owner(k, new) for k in keys)
ring_moved = sum(ring_owner(k, ring_old) != ring_owner(k, ring_new) for k in keys)
print("modulo moved:", mod_moved, "| ring moved:", ring_moved)
show([mod_moved, ring_moved], "keys moved: modulo vs ring")

load = {s: 0 for s in new}
for k in keys:
    load[ring_owner(k, ring_new)] += 1
show(list(load.values()), "keys per server (A to E)")

