let seed = 42;
function rand() { seed = (seed * 16807) % 2147483647; return seed / 2147483647; }

function makeShop() {
  const charges = new Array(20).fill(0);
  const saved = {};
  function server(order, key) {
    if (key && saved[key]) return saved[key];
    charges[order]++;
    if (key) saved[key] = "ok";
    return "ok";
  }
  function send(order, key) {
    const reply = server(order, key);
    return rand() < 0.3 ? null : reply;
  }
  return { charges, send };
}

function blind(shop, order) {
  for (let i = 0; i < 10; i++) {
    if (shop.send(order, null)) return;
  }
}

function careful(shop, order) {
  const key = "order-" + order;
  let waited = 0;
  for (let i = 0; i < 10; i++) {
    if (shop.send(order, key)) return waited;
    waited += 100 * 2 ** i * (0.5 + rand() / 2);
  }
  return waited;
}

const A = makeShop(), B = makeShop();
for (let o = 0; o < 20; o++) {
  blind(A, o);
  careful(B, o);
}
const total = (list) => list.reduce((a, b) => a + b, 0);
show(A.charges, "A: blind retries, charges per order");
show(B.charges, "B: idempotency key, charges per order");
print("A charged", total(A.charges), "times. B charged", total(B.charges), "times. Orders: 20");

