const counts = { Ada: 8, Bo: 6, Cy: 4, Di: 2 };
const playlist = Object.entries(counts).flatMap(([a, n]) => Array(n).fill(a));

function fisherYates(list) {
  const a = [...list];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

function spreadShuffle(list) {
  const scored = [];
  for (const artist of new Set(list)) {
    const n = list.filter(s => s === artist).length;
    const offset = Math.random() / n;
    for (let k = 0; k < n; k++) {
      const jitter = (Math.random() - 0.5) * 0.3 / n;
      scored.push({ artist, pos: k / n + offset + jitter });
    }
  }
  scored.sort((x, y) => x.pos - y.pos);
  return scored.map(s => s.artist);
}

function clumps(order) {
  let pairs = 0;
  for (let i = 1; i < order.length; i++) {
    if (order[i] === order[i - 1]) pairs++;
  }
  return pairs;
}

let randomTotal = 0, spreadTotal = 0;
for (let t = 0; t < 200; t++) {
  randomTotal += clumps(fisherYates(playlist));
  spreadTotal += clumps(spreadShuffle(playlist));
}
show([randomTotal / 200, spreadTotal / 200], "Avg back-to-back pairs: Fisher–Yates vs spread");

const rows = o => [o.slice(0, 10), o.slice(10)];
show(rows(fisherYates(playlist)), "Fisher–Yates sample");
show(rows(spreadShuffle(playlist)), "Spread sample");

