import random
random.seed(7)
backups = []

def server_ms():
    if random.random() < 0.02:
        return random.uniform(200, 1000)
    return random.uniform(10, 20)

def plain():
    return server_ms()

def hedged():
    first = server_ms()
    if first <= 30:
        return first
    backups.append(1)
    return min(first, 30 + server_ms())

def page(call):
    return max(call() for _ in range(50))

def pct(xs, p):
    xs = sorted(xs)
    return xs[int(len(xs) * p / 100) - 1]

plain_pages = [page(plain) for _ in range(500)]
hedged_pages = [page(hedged) for _ in range(500)]

show([round(pct(plain_pages, 50)), round(pct(plain_pages, 99))], "No hedging: median, p99 ms")
show([round(pct(hedged_pages, 50)), round(pct(hedged_pages, 99))], "Hedged: median, p99 ms")
total = 500 * 50
show({"calls": total, "backups sent": len(backups), "extra load %": round(100 * len(backups) / total, 1)}, "Cost of hedging")

