import random
random.seed(7)
N, POSTS, READS, STAR = 200, 500, 5000, 0

follows = {u: set(random.sample(range(N), 10)) - {u} for u in range(N)}
for u in range(1, N): follows[u].add(STAR)
followers = {u: [v for v in range(N) if u in follows[v]] for u in range(N)}
authors = [STAR if random.random() < .2 else random.randrange(N) for _ in range(POSTS)]
readers = [random.randrange(N) for _ in range(READS)]

def on_read():
    write = POSTS
    read = sum(len(follows[r]) for r in readers)
    return write, read

def on_write(skip=-1):
    inbox = {u: [] for u in range(N)}
    write = 0
    for post, a in enumerate(authors):
        if a == skip:
            write += 1
        else:
            for f in followers[a]:
                inbox[f].append(post)
                write += 1
    read = sum(1 + (skip in follows[r]) for r in readers)
    return write, read

results = {'read': on_read(), 'write': on_write(), 'hybrid': on_write(STAR)}
show([w for w, r in results.values()], 'Write work: read-time | write-time | hybrid')
show([r for w, r in results.values()], 'Read work: read-time | write-time | hybrid')
for name, (w, r) in results.items():
    print(name, 'total work:', w + r)

