const start = "the cat sat";
const A = { type: "ins", pos: 4, text: "big ", site: 1 };
const B = { type: "del", pos: 0, len: 4, site: 2 };

function apply(s, op) {
  if (op.type === "ins") return s.slice(0, op.pos) + op.text + s.slice(op.pos);
  return s.slice(0, op.pos) + s.slice(op.pos + op.len);
}

function transform(a, b) {
  const t = { ...a };
  if (a.type === "ins" && b.type === "ins") {
    if (b.pos < a.pos || (b.pos === a.pos && b.site < a.site)) t.pos += b.text.length;
  } else if (a.type === "ins" && b.type === "del") {
    if (b.pos < a.pos) t.pos -= Math.min(b.len, a.pos - b.pos);
  } else if (a.type === "del" && b.type === "ins") {
    if (b.pos <= a.pos) t.pos += b.text.length;
  }
  return t;
}

const naiveAB = apply(apply(start, A), B);
const naiveBA = apply(apply(start, B), A);
const smartAB = apply(apply(start, A), transform(B, A));
const smartBA = apply(apply(start, B), transform(A, B));

show([
  { how: "obvious", order: "A then B", result: naiveAB },
  { how: "obvious", order: "B then A", result: naiveBA },
  { how: "transformed", order: "A then B", result: smartAB },
  { how: "transformed", order: "B then A", result: smartBA },
], "Do the copies agree?");
